import React, { useCallback, useEffect, useState } from "react";
import "./movie-grid.scss";
import { useHistory, useParams } from "react-router";
import MovieCard from "./../movie-card/MovieCard";
import tmdbApi, { category, movieType, tvType } from "../../api/tmdbApi";
import Button, { OutlineButton } from "../button/Button";
import Input from "../input/Input";
import * as Config from "./../../constants/Config";

// Import your exported Python JSON data
import customGenreData from "../../assets/top10_movies_by_genre.json";

const MovieGrid = (props) => {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [totalPage, setTotalPage] = useState(0);

  const { keyword, genreName } = useParams(); // Capture genreName from URL if configured

  useEffect(() => {
    const getList = async () => {
      // Check if we are viewing a genre route
      if (genreName) {
        // Fetch from your local Python data export
        const genreMovies = customGenreData[genreName.toLowerCase()] || [];
        setItems(genreMovies);
        setTotalPage(1); // Since you have top 10, all fit on one page
      } else if (keyword === undefined) {
        // Existing TMDB logic for upcoming/popular
        const params = {};
        let response = null;
        switch (props.category) {
          case category.movie:
            response = await tmdbApi.getMoviesList(movieType.upcoming, { params });
            break;
          default:
            response = await tmdbApi.getTvList(tvType.popular, { params });
        }
        setItems(response.results);
        setTotalPage(response.total_pages);
      } else {
        // Existing TMDB Search logic
        const params = { query: keyword };
        const response = await tmdbApi.search(props.category, { params });
        setItems(response.results);
        setTotalPage(response.total_pages);
      }
    };
    getList();
  }, [keyword, genreName, props.category]);

  const loadMore = useCallback(async () => {
    // Load more logic if pagination is needed for TMDB
  }, []);

  return (
    <>
      <div className="section mb-3">
        {props.isGenre ? (
          <MovieGenre category={props.category} />
        ) : (
          <MovieSearch category={props.category} keyword={keyword} />
        )}
      </div>
      <div className="movie-grid">
        {items.map((item, index) => (
          <MovieCard key={index} category={props.category} item={item} />
        ))}
      </div>
    </>
  );
};

// ... Keep MovieSearch and MovieGenre components as they are ...
